#!/bin/bash
# long log lines: each wraps at any pane width
for i in $(seq 1 160); do printf '2026-11-05T12:%02d:%02d.%03dZ INFO resize.frame-owner pane=p%d width=%d step=%d message="%s"\n' $((i/60)) $((i%60)) $((i*7%1000)) $((i%7)) $((300+i)) $i 'the quick brown fox jumps over the lazy dog while the column resizes and the text wraps again at the new width'; done
